//! Tests of the yEnc decoder (internal/usenet/yenc/*_test.go). Expected values
//! are those of the Go tests; the fuzz seeds were generated by the Go test
//! encoder.
const std = @import("std");
const testing = std.testing;
const Io = std.Io;
const yenc = @import("yenc.zig");
const Decoder = yenc.Decoder;
const Part = @import("yenc_types.zig").Part;

const Lines = []const []const u8;

/// Feeds lines to a fresh Decoder and finishes it. `a` should be an arena:
/// the Part lives in it.
fn decode(a: std.mem.Allocator, lines: Lines) yenc.Error!Part {
    var d: Decoder = .init(a);
    for (lines) |l| try d.feed(l);
    return d.finish();
}

fn expectDecodeError(want: yenc.Error, lines: Lines) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    try testing.expectError(want, decode(arena.allocator(), lines));
}

// A yEnc 1.3 encoder for tests (encoder_test.go). It does not use the decoder.

/// Encodes `file` as Article bodies of at most `part_size` decoded bytes each,
/// with data lines of `line_len` encoded characters (one more when the last
/// character is escaped). A file that fits in one part is a single-part file:
/// no part=, no =ypart, and crc32= in the trailer.
fn encodeArticles(a: std.mem.Allocator, name: []const u8, file: []const u8, part_size: usize, line_len: usize) ![]const Lines {
    var articles: std.ArrayList(Lines) = .empty;
    if (file.len <= part_size) {
        var lines: std.ArrayList([]const u8) = .empty;
        try lines.append(a, try std.fmt.allocPrint(a, "=ybegin line={d} size={d} name={s}", .{ line_len, file.len, name }));
        try encodeLines(a, &lines, file, line_len);
        try lines.append(a, try std.fmt.allocPrint(a, "=yend size={d} crc32={x:0>8}", .{ file.len, std.hash.Crc32.hash(file) }));
        try articles.append(a, lines.items);
        return articles.items;
    }
    const total = (file.len + part_size - 1) / part_size;
    for (1..total + 1) |n| {
        const begin = (n - 1) * part_size;
        const end = @min(begin + part_size, file.len);
        const data = file[begin..end];
        var lines: std.ArrayList([]const u8) = .empty;
        try lines.append(a, try std.fmt.allocPrint(a, "=ybegin part={d} total={d} line={d} size={d} name={s}", .{ n, total, line_len, file.len, name }));
        try lines.append(a, try std.fmt.allocPrint(a, "=ypart begin={d} end={d}", .{ begin + 1, end }));
        try encodeLines(a, &lines, data, line_len);
        var trailer = try std.fmt.allocPrint(a, "=yend size={d} part={d} pcrc32={x:0>8}", .{ data.len, n, std.hash.Crc32.hash(data) });
        if (n == total) trailer = try std.fmt.allocPrint(a, "{s} crc32={x:0>8}", .{ trailer, std.hash.Crc32.hash(file) });
        try lines.append(a, trailer);
        try articles.append(a, lines.items);
    }
    return articles.items;
}

/// NUL, LF, CR and '=' are always escaped; tab and space are escaped at the
/// start or end of a line, and '.' at the start of a line, so the lines
/// survive NNTP transport.
fn encodeLines(a: std.mem.Allocator, lines: *std.ArrayList([]const u8), data: []const u8, line_len: usize) !void {
    var line: std.ArrayList(u8) = .empty;
    for (data, 0..) |b, i| {
        const c = b +% 42;
        const first = line.items.len == 0;
        const last = line.items.len + 1 >= line_len or i == data.len - 1;
        const escape = switch (c) {
            0, '\n', '\r', '=' => true,
            '\t', ' ' => first or last,
            '.' => first,
            else => false,
        };
        if (escape) {
            try line.appendSlice(a, &.{ '=', c +% 64 });
        } else {
            try line.append(a, c);
        }
        if (line.items.len >= line_len) {
            try lines.append(a, line.items);
            line = .empty;
        }
    }
    if (line.items.len > 0) try lines.append(a, line.items);
}

fn allByteValues(a: std.mem.Allocator, copies: usize) ![]u8 {
    const b = try a.alloc(u8, 256 * copies);
    for (b, 0..) |*x, i| x.* = @truncate(i);
    return b;
}

fn randomBytes(a: std.mem.Allocator, rng_seed: u64, n: usize) ![]u8 {
    var prng: std.Random.DefaultPrng = .init(rng_seed);
    const b = try a.alloc(u8, n);
    prng.random().bytes(b);
    return b;
}

fn repeat(a: std.mem.Allocator, pattern: []const u8, times: usize) ![]u8 {
    const b = try a.alloc(u8, pattern.len * times);
    for (0..times) |i| @memcpy(b[i * pattern.len ..][0..pattern.len], pattern);
    return b;
}

fn joinLines(a: std.mem.Allocator, lines: Lines, sep: []const u8) ![]u8 {
    return std.mem.join(a, sep, lines);
}

// Tests

test "the test encoder matches the Go one" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const articles = try encodeArticles(a, "seed.bin", try allByteValues(a, 2), 200, 32);
    try testing.expectEqual(3, articles.len);
    for (articles, seeds[0..3]) |lines, want| {
        try testing.expectEqualStrings(want, try joinLines(a, lines, "\n"));
    }
    const one = try encodeArticles(a, "one.bin", "123456789", 100, 128);
    try testing.expectEqualStrings(seeds[3], try joinLines(a, one[0], "\n"));
}

test "decodes a single-part article" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin line=128 size=9 name=check.txt",
        "[\\]^_`abc",
        "=yend size=9 crc32=cbf43926",
    });
    try testing.expectEqualStrings("123456789", p.data);
    try testing.expectEqualStrings("check.txt", p.name);
    try testing.expectEqual(9, p.size);
    try testing.expectEqual(1, p.begin);
    try testing.expectEqual(9, p.end);
    try testing.expectEqual(1, p.part_number);
    try testing.expectEqual(1, p.total_parts);
    try testing.expectEqual(0xcbf43926, p.crc32);
    try testing.expect(p.crcMatch());
}

test "decodes escaped critical characters" {
    // D6 E0 E3 13 map to NUL LF CR '=' and must be escaped; F6 DF 04 map to
    // space, tab and '.', which encoders escape at line edges.
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin line=128 size=7 name=escapes.bin",
        "=@=J=M=}=`=I=n",
        "=yend size=7 crc32=de67a556",
    });
    try testing.expectEqualSlices(u8, &.{ 0xD6, 0xE0, 0xE3, 0x13, 0xF6, 0xDF, 0x04 }, p.data);
    try testing.expect(p.crcMatch());
}

test "rejects a line ending in the escape character" {
    try expectDecodeError(error.Malformed, &.{ "=ybegin line=128 size=1 name=x", "=", "=yend size=1" });
}

test "ignores line terminators, also inside a line" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin line=128 size=9 name=check.txt\r\n",
        "[\\]^\r\n",
        "_`a\n",
        "b\rc\r\n",
        "=yend size=9 crc32=cbf43926\r\n",
    });
    try testing.expectEqualStrings("123456789", p.data);
    try testing.expectEqualStrings("check.txt", p.name);
    try testing.expect(p.crcMatch());
}

test "an escape character skips line terminators to its operand" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin line=128 size=2 name=x",
        "=\r\n}[",
        "=yend size=2",
    });
    try testing.expectEqualSlices(u8, &.{ '}' -% 106, '1' }, p.data);
    try expectDecodeError(error.Malformed, &.{ "=ybegin line=128 size=2 name=x", "a=\r\n", "=yend size=2" });
}

test "takes a leading double dot literally" {
    // Dot-unstuffing is the NNTP layer's job. A line that still starts with
    // ".." holds two '.' bytes, each decoding to 0x2E-42.
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{ "=ybegin line=128 size=3 name=dot.bin", "..[", "=yend size=3" });
    try testing.expectEqualSlices(u8, &.{ 0x04, 0x04, '1' }, p.data);
}

test "decodes a multipart post" {
    // A 9-byte file "123456789" posted in two Articles.
    const Article = struct { lines: Lines, data: []const u8, begin: i64, end: i64, number: u32 };
    const articles = [_]Article{
        .{
            .lines = &.{
                "=ybegin part=1 total=2 line=128 size=9 name=my file (1).txt",
                "=ypart begin=1 end=4",
                "[\\]^",
                "=yend size=4 part=1 pcrc32=9be3e0a3",
            },
            .data = "1234",
            .begin = 1,
            .end = 4,
            .number = 1,
        },
        .{
            .lines = &.{
                "=ybegin part=2 total=2 line=128 size=9 name=my file (1).txt",
                "=ypart begin=5 end=9",
                "_`abc",
                "=yend size=5 part=2 pcrc32=131da070 crc32=cbf43926",
            },
            .data = "56789",
            .begin = 5,
            .end = 9,
            .number = 2,
        },
    };
    for (articles) |art| {
        var arena: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena.deinit();
        const p = try decode(arena.allocator(), art.lines);
        try testing.expectEqualStrings(art.data, p.data);
        try testing.expectEqualStrings("my file (1).txt", p.name);
        try testing.expectEqual(9, p.size);
        try testing.expectEqual(art.number, p.part_number);
        try testing.expectEqual(2, p.total_parts);
        try testing.expectEqual(art.begin, p.begin);
        try testing.expectEqual(art.end, p.end);
        try testing.expect(p.crcMatch());
    }
}

test "returns data with a CRC mismatch" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin line=128 size=9 name=check.txt",
        "[\\]^_`abd", // last byte corrupted
        "=yend size=9 crc32=cbf43926",
    });
    try testing.expectEqualStrings("12345678:", p.data);
    try testing.expect(p.has_expected_crc);
    try testing.expectEqual(0xcbf43926, p.expected_crc32);
    try testing.expect(!p.crcMatch());
}

test "a part without an announced CRC does not match" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{ "=ybegin line=128 size=9 name=check.txt", "[\\]^_`abc", "=yend size=9" });
    try testing.expect(!p.has_expected_crc);
    try testing.expectEqual(0xcbf43926, p.crc32);
    try testing.expect(!p.crcMatch());
}

test "a multipart trailer's whole-file CRC is ignored" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin part=2 total=2 line=128 size=9 name=check.txt",
        "=ypart begin=5 end=9",
        "_`abc",
        "=yend size=5 part=2 crc32=cbf43926",
    });
    try testing.expect(!p.has_expected_crc);
}

test "rejects an article without a header" {
    try expectDecodeError(error.NoHeader, &.{});
    try expectDecodeError(error.NoHeader, &.{"[\\]^_`abc"});
    try expectDecodeError(error.NoHeader, &.{ "[\\]^_`abc", "=yend size=9 crc32=cbf43926" });
}

test "rejects a decoded length different from the range" {
    // short multipart
    try expectDecodeError(error.Length, &.{ "=ybegin part=1 total=2 line=128 size=9 name=x", "=ypart begin=1 end=4", "[\\]", "=yend size=3 part=1" });
    // long multipart
    try expectDecodeError(error.Length, &.{ "=ybegin part=1 total=2 line=128 size=9 name=x", "=ypart begin=1 end=4", "[\\]^_", "=yend size=5 part=1" });
    // short single part
    try expectDecodeError(error.Length, &.{ "=ybegin line=128 size=9 name=x", "[\\]^_", "=yend size=5" });
}

test "rejects a trailer size different from the decoded length" {
    try expectDecodeError(error.Length, &.{ "=ybegin part=1 total=2 line=128 size=9 name=x", "=ypart begin=1 end=4", "[\\]^", "=yend size=5 part=1" });
}

test "rejects an invalid part range" {
    const cases = [_][]const u8{
        "=ypart begin=5 end=4", // end before begin
        "=ypart begin=0 end=4", // begin zero
        "=ypart begin=5 end=10", // end past size
    };
    for (cases) |ypart| {
        var d: Decoder = .init(testing.allocator);
        defer d.deinit();
        try d.feed("=ybegin part=2 total=2 line=128 size=9 name=x");
        try testing.expectError(error.Range, d.feed(ypart));
    }
}

test "rejects an oversized file or part" {
    var buf: [128]u8 = undefined;
    try expectDecodeError(error.TooLarge, &.{try std.fmt.bufPrint(&buf, "=ybegin part=1 line=128 size={d} name=x", .{yenc.max_file_size + 1})});
    try expectDecodeError(error.TooLarge, &.{try std.fmt.bufPrint(&buf, "=ybegin line=128 size={d} name=x", .{yenc.max_part_size + 1})});
    var buf2: [128]u8 = undefined;
    try expectDecodeError(error.TooLarge, &.{
        try std.fmt.bufPrint(&buf, "=ybegin part=1 line=128 size={d} name=x", .{yenc.max_file_size}),
        try std.fmt.bufPrint(&buf2, "=ypart begin=1 end={d}", .{yenc.max_part_size + 1}),
    });
}

test "accepts parts at the limits" {
    var d: Decoder = .init(testing.allocator);
    defer d.deinit();
    var buf: [128]u8 = undefined;
    try d.feed(try std.fmt.bufPrint(&buf, "=ybegin part=2 line=128 size={d} name=x", .{yenc.max_file_size}));
    try d.feed(try std.fmt.bufPrint(&buf, "=ypart begin={d} end={d}", .{ yenc.max_file_size - yenc.max_part_size + 1, yenc.max_file_size }));
}

test "rejects data beyond the declared range as it arrives" {
    var d: Decoder = .init(testing.allocator);
    defer d.deinit();
    try d.feed("=ybegin part=1 total=2 line=128 size=9 name=x");
    try d.feed("=ypart begin=1 end=4");
    try d.feed("[\\]");
    try testing.expectError(error.Length, d.feed("^_"));
}

test "errors are sticky" {
    var d: Decoder = .init(testing.allocator);
    defer d.deinit();
    try d.feed("=ybegin part=1 total=2 line=128 size=9 name=x");
    try d.feed("=ypart begin=1 end=4");
    try testing.expectError(error.Length, d.feed("[\\]^_")); // one byte too many
    try testing.expectError(error.Length, d.feed("=yend size=4 part=1"));
    try testing.expectError(error.Length, d.finish());
}

test "rejects an article without a trailer" {
    try expectDecodeError(error.Malformed, &.{ "=ybegin line=128 size=9 name=check.txt", "[\\]^_`abc" });
}

test "ignores text around the encoded part" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "",
        "Posted with SomeClient 1.0",
        "=ybegin line=128 size=9 name=check.txt",
        "[\\]^_`abc",
        "=yend size=9 crc32=cbf43926",
        "",
        "-- ",
        "signature",
    });
    try testing.expectEqualStrings("123456789", p.data);
    try testing.expect(p.crcMatch());
}

test "rejects misplaced keyword lines" {
    const multi = "=ybegin part=1 total=2 line=128 size=9 name=x";
    const single = "=ybegin line=128 size=9 name=x";
    // multipart without ypart
    try expectDecodeError(error.Malformed, &.{ multi, "[\\]^", "=yend size=4 part=1" });
    // ypart after data
    try expectDecodeError(error.Malformed, &.{ multi, "[\\]^", "=ypart begin=1 end=4", "=yend size=4 part=1" });
    // ypart twice
    try expectDecodeError(error.Malformed, &.{ multi, "=ypart begin=1 end=4", "=ypart begin=1 end=4", "[\\]^", "=yend size=4 part=1" });
    // ypart in a single part
    try expectDecodeError(error.Malformed, &.{ single, "=ypart begin=1 end=9", "[\\]^_`abc", "=yend size=9" });
    // nested ybegin
    try expectDecodeError(error.Malformed, &.{ single, single, "[\\]^_`abc", "=yend size=9" });
    // unknown keyword
    try expectDecodeError(error.Malformed, &.{ single, "=yfoo bar=1", "[\\]^_`abc", "=yend size=9" });
    // =yend without its space
    try expectDecodeError(error.Malformed, &.{ single, "[\\]^_`abc", "=yend" });
}

test "rejects malformed fields" {
    const data = "[\\]^";
    const ypart = "=ypart begin=1 end=4";
    const yend = "=yend size=4 part=1";
    const ybegin = "=ybegin part=1 total=2 line=128 size=9 name=x";
    const Case = struct { ybegin: []const u8, ypart: []const u8, yend: []const u8 };
    const cases = [_]Case{
        .{ .ybegin = "=ybegin part=1 total=2 line=128 name=x", .ypart = ypart, .yend = yend }, // missing size
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=9", .ypart = ypart, .yend = yend }, // missing name
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=-9 name=x", .ypart = ypart, .yend = yend }, // negative size
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=+9 name=x", .ypart = ypart, .yend = yend }, // signed size
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=0x9 name=x", .ypart = ypart, .yend = yend }, // hex size
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=9_0 name=x", .ypart = ypart, .yend = yend }, // separator
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=99999999999999999999 name=x", .ypart = ypart, .yend = yend }, // overflowing size
        .{ .ybegin = "=ybegin part=0 total=2 line=128 size=9 name=x", .ypart = ypart, .yend = "=yend size=4 part=0" }, // part zero
        .{ .ybegin = "=ybegin part=one total=2 line=128 size=9 name=x", .ypart = ypart, .yend = yend },
        .{ .ybegin = "=ybegin part=3 total=2 line=128 size=9 name=x", .ypart = ypart, .yend = "=yend size=4 part=3" }, // part beyond total
        .{ .ybegin = "=ybegin part=1 total=0 line=128 size=9 name=x", .ypart = ypart, .yend = yend }, // total zero
        .{ .ybegin = "=ybegin part=4294967297 line=128 size=9 name=x", .ypart = ypart, .yend = "=yend size=4 part=4294967297" },
        .{ .ybegin = "=ybegin part=1 total=4294967297 line=128 size=9 name=x", .ypart = ypart, .yend = yend },
        .{ .ybegin = "=ybegin part=1 total=2 line=x size=9 name=x", .ypart = ypart, .yend = yend }, // line not a number
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=9 size=4 name=x", .ypart = ypart, .yend = yend }, // duplicate size
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size= name=x", .ypart = ypart, .yend = yend }, // empty value
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size name=x", .ypart = ypart, .yend = yend }, // key without value
        .{ .ybegin = ybegin, .ypart = "=ypart begin=1", .yend = yend }, // ypart missing end
        .{ .ybegin = ybegin, .ypart = "=ypart begin=a end=4", .yend = yend },
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend part=1" }, // yend missing size
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend size=4x part=1" },
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend size=4 part=2" }, // part mismatch
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend size=4 part=1 pcrc32=xyz" },
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend size=4 part=1 pcrc32=19be3e0a3" }, // too long
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend size=4 part=1 pcrc32=+be3e0a3" }, // signed
        .{ .ybegin = ybegin, .ypart = ypart, .yend = "=yend size=4 part=1 pcrc32=" }, // empty
    };
    for (cases) |c| {
        errdefer std.debug.print("case: {s} / {s} / {s}\n", .{ c.ybegin, c.ypart, c.yend });
        try expectDecodeError(error.Malformed, &.{ c.ybegin, c.ypart, data, c.yend });
    }
}

test "ignores unknown header tokens" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin part=1 total=2 line=128 size=9 flavor=x junk flavor=y empty= name=x",
        "=ypart begin=1 end=4 extra=1 extra=2 odd",
        "[\\]^",
        "=yend size=4 part=1 pcrc32=9be3e0a3 extra=1 extra=2 odd",
    });
    try testing.expectEqualStrings("1234", p.data);
    try testing.expectEqualStrings("x", p.name);
    try testing.expect(p.crcMatch());
}

test "fields are split on Unicode white space like Go's strings.Fields" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    // NBSP (C2 A0), U+3000 and a tab between the fields; a lookalike byte
    // sequence that is not a space (C2 A1) stays part of the token (an unknown key).
    const p = try decode(arena.allocator(), &.{
        "=ybegin part=1\xc2\xa0total=2\tline=128\xe3\x80\x80junk\xc2\xa1=7 size=9 name=x",
        "=ypart begin=1 end=4",
        "[\\]^",
        "=yend size=4 part=1",
    });
    try testing.expectEqual(9, p.size);
    try testing.expectEqual(2, p.total_parts);
}

test "rejects duplicate known keys in the part and trailer lines" {
    const ybegin = "=ybegin part=1 total=2 line=128 size=9 name=x";
    try expectDecodeError(error.Malformed, &.{ ybegin, "=ypart begin=1 end=4 end=4", "[\\]^", "=yend size=4 part=1" });
    try expectDecodeError(error.Malformed, &.{ ybegin, "=ypart begin=1 end=4", "[\\]^", "=yend size=4 pcrc32=9be3e0a3 pcrc32=9be3e0a3" });
    try expectDecodeError(error.Malformed, &.{ ybegin, "=ypart begin=1 end=4", "[\\]^", "=yend size=4 size=4" });
}

test "the name is the rest of the header line" {
    const Case = struct { ybegin: []const u8, want: []const u8 };
    const cases = [_]Case{
        .{ .ybegin = "=ybegin part=1 total=2 line=128 size=9 name=a b  size=1.txt ", .want = "a b  size=1.txt " },
        .{ .ybegin = "=ybegin line=128 size=9 part=1 name=../../etc/passwd", .want = "../../etc/passwd" },
        .{ .ybegin = "=ybegin part=1 size=9 name=", .want = "" },
        .{ .ybegin = "=ybegin part=1 size=9 name=a name=b", .want = "a name=b" },
    };
    for (cases) |c| {
        var arena: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena.deinit();
        const p = try decode(arena.allocator(), &.{ c.ybegin, "=ypart begin=1 end=4", "[\\]^", "=yend size=4 part=1" });
        try testing.expectEqualStrings(c.want, p.name);
    }
}

test "a multipart header without total= has zero total parts, as in Go" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{ "=ybegin part=1 size=9 name=x", "=ypart begin=1 end=4", "[\\]^", "=yend size=4" });
    try testing.expectEqual(0, p.total_parts);
    // total= without part= is a single part.
    const q = try decode(arena.allocator(), &.{ "=ybegin total=5 size=4 name=x", "[\\]^", "=yend size=4" });
    try testing.expectEqual(1, q.total_parts);
}

test "parses an uppercase CRC" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{
        "=ybegin part=1 total=2 line=128 size=9 name=x",
        "=ypart begin=1 end=4",
        "[\\]^",
        "=yend size=4 part=1 pcrc32=9BE3E0A3",
    });
    try testing.expect(p.crcMatch());
}

test "an empty single-part file" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const p = try decode(arena.allocator(), &.{ "=ybegin line=128 size=0 name=e", "=yend size=0 crc32=00000000" });
    try testing.expectEqual(0, p.data.len);
    try testing.expect(p.crcMatch());
}

test "round trips files" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Case = struct { file: []const u8, part_size: usize, line_len: usize };
    const cases = [_]Case{
        .{ .file = "", .part_size = 100, .line_len = 128 },
        .{ .file = try allByteValues(a, 4), .part_size = 4096, .line_len = 128 },
        .{ .file = try allByteValues(a, 1), .part_size = 4096, .line_len = 1 },
        .{ .file = try allByteValues(a, 3), .part_size = 4096, .line_len = 7 },
        .{ .file = try repeat(a, &.{ 0xF6, 0xDF, 0x04, 0x01 }, 300), .part_size = 4096, .line_len = 3 },
        .{ .file = try randomBytes(a, 1, 100_000), .part_size = 16_384, .line_len = 128 },
        .{ .file = try randomBytes(a, 2, 50_001), .part_size = 10_000, .line_len = 256 },
        .{ .file = try repeat(a, &.{ 0xD6, 0xE0, 0xE3, 0x13 }, 5000), .part_size = 3000, .line_len = 128 },
    };
    for (cases) |c| {
        const articles = try encodeArticles(a, "file.bin", c.file, c.part_size, c.line_len);
        const got = try a.alloc(u8, c.file.len);
        // Decode out of order, as the scheduler may deliver them.
        var i = articles.len;
        while (i > 0) {
            i -= 1;
            const p = try decode(a, articles[i]);
            try testing.expectEqualStrings("file.bin", p.name);
            try testing.expectEqual(@as(i64, @intCast(c.file.len)), p.size);
            try testing.expectEqual(i + 1, p.part_number);
            try testing.expect(p.crcMatch());
            @memcpy(got[@intCast(p.begin - 1)..][0..p.data.len], p.data);
        }
        try testing.expectEqualSlices(u8, c.file, got);
    }
}

test "the SWAR fast path and the byte loop agree at every alignment" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const file = try randomBytes(a, 7, 3000);
    for (1..40) |line_len| {
        const articles = try encodeArticles(a, "f", file, 5000, line_len);
        const p = try decode(a, articles[0]);
        try testing.expectEqualSlices(u8, file, p.data);
        try testing.expect(p.crcMatch());
    }
}

test "the decoder frees what it owns" {
    // std.testing.allocator reports a leak or a double free.
    {
        // Dropped half way.
        var d: Decoder = .init(testing.allocator);
        defer d.deinit();
        try d.feed("=ybegin line=128 size=9 name=x");
    }
    {
        // Failed.
        var d: Decoder = .init(testing.allocator);
        defer d.deinit();
        try d.feed("=ybegin line=128 size=1 name=x");
        try testing.expectError(error.Length, d.feed("ab"));
    }
    {
        // Finished: the caller frees.
        var d: Decoder = .init(testing.allocator);
        defer d.deinit();
        for ([_][]const u8{ "=ybegin line=128 size=1 name=xyz", "1", "=yend size=1" }) |l| try d.feed(l);
        const p = try d.finish();
        const again = try d.finish();
        try testing.expectEqualSlices(u8, p.data, again.data);
        testing.allocator.free(p.data);
        testing.allocator.free(p.name);
    }
    {
        // Reused after reset.
        var d: Decoder = .init(testing.allocator);
        defer d.deinit();
        try d.feed("=ybegin line=128 size=1 name=x");
        d.reset();
        try testing.expectError(error.NoHeader, d.finish());
        try d.feed("=ybegin line=128 size=1 name=y");
    }
    {
        // Out of memory in each allocation.
        var failing: testing.FailingAllocator = .init(testing.allocator, .{ .fail_index = 1 });
        var d: Decoder = .init(failing.allocator());
        defer d.deinit();
        try testing.expectError(error.OutOfMemory, d.feed("=ybegin line=128 size=1 name=x"));
    }
}

test "throughput of decoding 64 MiB" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const part_size = 716_800; // a typical Article part
    const file = try randomBytes(a, 42, part_size);
    const lines = (try encodeArticles(a, "bench.bin", file, part_size, 128))[0];
    const total = 64 << 20;
    const rounds = total / part_size + 1;
    const start = Io.Clock.now(.awake, testing.io);
    for (0..rounds) |_| {
        var part_arena: std.heap.ArenaAllocator = .init(testing.allocator);
        defer part_arena.deinit();
        const p = try decode(part_arena.allocator(), lines);
        try testing.expect(p.crcMatch());
    }
    const ns: u64 = @intCast(start.durationTo(Io.Clock.now(.awake, testing.io)).nanoseconds);
    const mb_s = @as(f64, @floatFromInt(rounds * part_size)) / 1e6 / (@as(f64, @floatFromInt(ns)) / 1e9);
    std.debug.print("yenc: decoded {d} MB at {d:.0} MB/s ({s})\n", .{ rounds * part_size / 1_000_000, mb_s, @tagName(@import("builtin").mode) });
    // Far below any real machine, even in a Debug build: only catches a
    // quadratic or otherwise absurd decoder.
    try testing.expect(mb_s > 5);
}

