fn seed(comptime s: []const u8) []const u8 {
    return &std.mem.toBytes(@as(u32, s.len)) ++ s;
}

// Feeds an arbitrary body, split into lines, to the Decoder. It must not
// crash or leak, must never hold more than max_part_size decoded bytes, and
// a part it accepts must be consistent with its declared range.
test "fuzz: feed and finish never crash or leak on any body" {
    try testing.fuzz({}, struct {
        fn one(_: void, smith: *testing.Smith) anyerror!void {
            var buf: [4096]u8 = undefined;
            const len = smith.slice(&buf);
            const body = buf[0..len];
            var d: Decoder = .init(testing.allocator);
            defer d.deinit();
            var failed: ?yenc.Error = null;
            var lines = std.mem.splitScalar(u8, body, '\n');
            while (lines.next()) |line| {
                d.feed(line) catch |e| {
                    failed = e;
                    break;
                };
            }
            const p = d.finish() catch return;
            if (failed != null) return error.FinishSucceededAfterFeedFailed;
            defer {
                testing.allocator.free(p.data);
                testing.allocator.free(p.name);
            }
            try testing.expectEqual(p.end - p.begin + 1, @as(i64, @intCast(p.data.len)));
            try testing.expect(p.data.len <= yenc.max_part_size);
            try testing.expect(p.begin >= 1 and p.end <= p.size and p.size <= yenc.max_file_size);
            try testing.expectEqual(std.hash.Crc32.hash(p.data), p.crc32);
        }
    }.one, .{ .corpus = &.{
        seed(seeds[0]),
        seed(seeds[1]),
        seed(seeds[2]),
        seed(seeds[3]),
        seed("=ybegin part=1 total=2 line=128 size=9 name=x\n=ypart begin=1 end=4\n[\\]^\n=yend size=4 part=1 pcrc32=9be3e0a3\n"),
        seed("=ybegin line=128 size=1 name=x\n=\n=yend size=1\n"),
        seed("=ybegin line=128 size=1 name=x\n=\r\n}\n=yend size=1 crc32=\n"),
        seed("junk\n=ybegin part=2 size=99999999999999 name=x\n=ypart begin=5 end=30\n=yend\n"),
    } });
}
